// discrete log: find smallest x >=0 such that g^x = a (mod p), or -1 if none
long long discrete_log(long long g, long long a, long long p) {
    g %= p; a %= p;
    if (a == 1) return 0;
    long long m = (long long)ceil(sqrt((long double)p));
    unordered_map<long long, long long> table;
    table.reserve(m * 2);
    table.max_load_factor(0.7);

    long long e = 1;
    for (long long j = 0; j < m; ++j) {
        if (!table.count(e)) table[e] = j;
        e = (__int128)e * g % p;
    }

    long long factor = modpow(g, p - 1 - m, p); // g^{-m}
    long long cur = a;
    for (long long i = 0; i <= m; ++i) {
        auto it = table.find(cur);
        if (it != table.end()) {
            long long ans = i * m + it->second;
            if (ans < p - 1) return ans;
        }
        cur = (__int128)cur * factor % p;
    }
    return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long a, b, p, x;
    if (!(cin >> a >> b >> p >> x)) return 0;

    long long phi = p - 1;

    // find primitive root g
    long long g = 2;
    while (true) {
        bool ok = true;
        long long n = phi;
        for (long long d = 2; d * d <= n; ++d) {
            if (n % d == 0) {
                while (n % d == 0) n /= d;
                if (modpow(g, phi / d, p) == 1) { ok = false; break; }
            }
        }
        if (ok && n > 1 && modpow(g, phi / n, p) == 1) ok = false;
        if (ok) break;
        ++g;
    }

    // compute discrete logs: a = g^A, b = g^B
    long long A = discrete_log(g, a, p);
    long long B = discrete_log(g, b, p);

    long long ans = 0;

    // precompute powers of a^k
    vector<long long> powA(phi);
    powA[0] = 1 % p;
    for (int i = 1; i < phi; ++i)
        powA[i] = (__int128)powA[i - 1] * a % p;

    // For each k in [0, phi-1], solve n * a^n ≡ b (mod p)
    // n ≡ b * (a^n)^{-1} (mod p)
    // Let n = t (mod p), and n ≡ k (mod phi), with n = k + t*phi
    // But we instead iterate over k and solve for t via discrete log.
    // Transform equation:
    // n * a^n ≡ b
    // => n ≡ b * (a^n)^{-1}
    // Let a = g^A, b = g^B, a^n = g^{A*n}
    // n * g^{A*n} ≡ g^B
    // Let n ≡ t (mod p), but we instead use:
    // For fixed k (n mod phi), we know a^n = a^k * a^{phi * q} = a^k
    // so equation in n mod p becomes:
    // n ≡ b * (a^k)^{-1} (mod p)
    // So n ≡ c_k (mod p), with c_k = b * inv(a^k)
    // Then n ≡ k (mod phi), n ≡ c_k (mod p).
    // Count solutions n <= x via CRT.

    long long invA0 = 1; // not used directly

    for (int k = 0; k < phi; ++k) {
        long long ak = powA[k];
        long long inv_ak = modpow(ak, p - 2, p);
        long long ck = (__int128)b * inv_ak % p;

        // Solve system:
        // n ≡ k (mod phi)
        // n ≡ ck (mod p)
        // Since gcd(phi, p) = 1, unique solution modulo phi*p
        long long m1 = phi, m2 = p;
        long long r1 = k, r2 = ck;

        // Solve using standard CRT:
        // n = r1 + m1 * t
        // r1 + m1 * t ≡ r2 (mod m2)
        // m1 * t ≡ (r2 - r1) (mod m2)
        long long diff = (r2 - r1) % m2;
        if (diff < 0) diff += m2;

        // Need inverse of m1 mod m2
        long long inv_m1 = modpow(m1 % m2, m2 - 2, m2);
        long long t = (__int128)diff * inv_m1 % m2;
        long long n0 = r1 + (__int128)m1 * t; // minimal non-negative solution

        if (n0 == 0) {
            // n must be positive
            n0 += m1 * m2;
        }

        if (n0 > x) continue;

        long long period = m1 * m2; // phi * p
        long long cnt = (x - n0) / period + 1;
        ans += cnt;
    }

    cout << ans << '\n';
    return 0;
